legal=[('terms-and-conditions','شرایط استفاده و سفارش',[('دامنه خدمات و توافق','مشخصات سفارش، خروجی، معیار پذیرش، زمان‌بندی و تعهدات دو طرف باید در پیشنهاد یا قرارداد همان پروژه نوشته شود. امکانات خارج از دامنه نیازمند بررسی و توافق جداگانه است.'),('دسترسی و مسئولیت اطلاعات','مالک کسب‌وکار مسئول صحت اطلاعات، مجوز استفاده از محتوا و دسترسی‌های ارائه‌شده است. دسترسی فنی فقط در حد نیاز پروژه و از مسیر امن تبادل می‌شود.'),('پرداخت و تحویل','مبلغ، مراحل پرداخت، مالیات احتمالی و شرایط توقف یا لغو باید پیش از خرید یا شروع کار مشخص شود. نسخه نمایشی قالب، قیمت یا تعهد نهایی یک پروژه محسوب نمی‌شود.'),('حقوق محتوا و رسیدگی به اختلاف','حقوق بهره‌برداری و اجزای دارای مجوز ثالث باید در توافق مشخص شود. مسیر ثبت درخواست و رسیدگی را از صفحه تماس اعلام کنید و شرایط واقعی کسب‌وکار را در این متن جایگزین کنید.')]),('warranty-policy','سیاست پشتیبانی و گارانتی',[('چه چیزی تحت پوشش است؟','پشتیبانی باید به محصول یا دامنه تحویل‌شده مرتبط باشد. رفع خطای قابل بازتولید، آموزش استفاده و توسعه قابلیت جدید موضوع‌های متفاوتی‌اند و حدود هرکدام باید روشن اعلام شود.'),('مدت و کانال ارائه خدمت','مدت پشتیبانی، ساعت پاسخگویی، کانال ثبت درخواست و شرایط تمدید را برای محصول یا پروژه واقعی درج کنید. این دمو به‌طور پیش‌فرض پشتیبانی رایگان، همیشگی یا پاسخ فوری تعهد نمی‌کند.'),('پیش‌نیاز بررسی فنی','شرح خطا، مراحل بازتولید، نسخه‌ها و تغییرات اخیر به بررسی کمک می‌کند. پیش از تغییر فنی نسخه پشتیبان تهیه کنید؛ رمز و داده محرمانه را در دیدگاه عمومی قرار ندهید.'),('موارد خارج از دامنه','تغییرات شخص ثالث، توسعه جدید یا ناسازگاری ناشی از محیط خارج از مشخصات نیازمند بررسی جداگانه است. نتیجه و هزینه احتمالی باید پیش از اقدام با مشتری هماهنگ شود.')]),('refund-policy','سیاست بازگشت وجه و لغو',[('بررسی پیش از خرید','ویژگی‌ها، نسخه، پیش‌نیازها، نوع مجوز و محدودیت محصول را بخوانید. در صورت ابهام، پیش از پرداخت پرسش خود را مطرح کنید.'),('ثبت درخواست','شرایط احراز، مهلت ثبت درخواست، مدارک لازم و کانال رسیدگی باید با توجه به محصول، قرارداد و حقوق قانونی مشتری توسط فروشنده مشخص شود. این دمو مهلت ۴۸ ساعته یا بازپرداخت نامشروط وعده نمی‌دهد.'),('رسیدگی و اعلام نتیجه','شناسه سفارش و شرح مشکل برای بررسی لازم است. مراحل بررسی، وضعیت استفاده یا تحویل و نتیجه تصمیم باید به مشتری اعلام شود.'),('لغو پروژه خدماتی','نحوه محاسبه کار انجام‌شده، هزینه‌های غیرقابل برگشت و تحویل خروجی‌های موجود در صورت توقف باید در قرارداد همان پروژه درج شود.')]),('privacy-policy','حریم خصوصی و داده‌های کاربران',[('داده‌های لازم برای ارتباط','فرم تماس می‌تواند نام، راه ارتباطی و متن درخواست را دریافت کند. فقط داده لازم را درخواست کنید و هدف استفاده را نزدیک فرم توضیح دهید.'),('سفارش، دیدگاه و نگهداری','سامانه سفارش و دیدگاه ممکن است داده‌های بیشتری ثبت کند. نوع داده، مدت نگهداری و دسترسی کارکنان را بر اساس فرایند واقعی و الزامات قانونی بنویسید.'),('سرویس‌های ثالث و کوکی‌ها','میزبان، درگاه پرداخت، ابزار تحلیل و نمایش تصویر ممکن است داده دریافت کنند. نام سرویس‌ها، هدف و شیوه کنترل کوکی‌های غیرضروری را پس از پیکربندی واقعی مشخص کنید.'),('درخواست مرتبط با داده','مسیر درخواست مشاهده، اصلاح یا حذف داده را اعلام کنید. احراز هویت و محدودیت‌های قانونی نگهداری باید در رسیدگی رعایت شوند.')]),('gdpr-compliance','شفافیت پردازش داده',[('اعمال‌پذیری مقررات','صرف داشتن این صفحه به معنی انطباق با GDPR نیست. ابتدا مشخص کنید مقررات کدام حوزه‌های قضایی بر فعالیت و مخاطبان شما اعمال می‌شود.'),('مبنای پردازش و رضایت','برای هر هدف پردازش، مبنای مناسب را تعیین کنید. رضایت اختیاری، قابل فهم و قابل بازپس‌گیری را در جایی که لازم است پیاده‌سازی کنید.'),('حقوق و انتقال داده','مسیر رسیدگی به حقوق اشخاص، قرارداد پردازشگران، انتقال بین‌المللی و سیاست نگهداری باید متناسب با خدمات واقعی بررسی شود.'),('امنیت و رسیدگی','نقش‌های دسترسی، مدیریت رخداد و مستندات داخلی را تدوین کنید. پیش از انتشار ادعای انطباق از بررسی حقوقی و فنی متناسب استفاده کنید.')]),('dmca-policy','Copyright and content removal requests',[('Respect for intellectual property','Only publish material you own or are permitted to use. Third-party software, images, fonts and documentation remain subject to their respective licenses.'),('Submitting a notice','Identify the copyrighted work, the exact location of the allegedly infringing material, your contact information and the basis for your authority to act. Do not include unnecessary sensitive data.'),('Review and response','The site operator should document receipt, assess the request and communicate appropriate action. This demo does not establish a designated agent or guarantee compliance with any particular jurisdiction.'),('Contact and applicable process','Provide the actual rights-contact channel and obtain legal advice about applicable notice, response and counter-notice requirements before using this draft as a published policy.')])]
for slug,title,parts in legal:data['legal'][slug]={'title':title,'sections':parts}
articles=[('elementor-based-wordpress-theme-architecture','پیش از سفارش سایت، این تصمیم‌ها را روشن کنید','هدف و مخاطب را دقیق تعریف کنید','ابزار را بعد از دامنه انتخاب کنید','فهرست صفحات به‌تنهایی بریف نیست. بنویسید چه کسی وارد سایت می‌شود، چه پرسشی دارد و چه اقدامی باید انجام دهد. این توصیف به تصمیم درباره ساختار محتوا و فرم‌ها کمک می‌کند.','وردپرس و المنتور برای بسیاری از سایت‌های محتوایی و شرکتی مناسب‌اند؛ فرایند اختصاصی، دسترسی پیچیده یا اتصال ویژه ممکن است توسعه جداگانه بخواهد. انتخاب را با هزینه نگهداری و مسئولیت به‌روزرسانی بسنجید.'),('website-and-social-media-seo-strategy-2026','سئو فنی از کجا شروع می‌شود؟ یک نقشه اولویت‌بندی','اول، امکان دسترسی و ایندکس','بعد، ساختار و تجربه صفحه','پیش از تولید انبوه محتوا، وضعیت پاسخ صفحات، مسیر خزیدن، robots و canonical را بررسی کنید. هر صفحه لازم نیست ایندکس شود؛ صفحات ارزشمند باید مسیر روشن و محتوای متمایز داشته باشند.','کارهای سئو را بر اساس داده موجود، اثر احتمالی و هزینه اجرا رتبه‌بندی کنید. رتبه و فروش تحت تأثیر عوامل متعددند؛ گزارش حرفه‌ای تغییر اجراشده و شاخص مشاهده‌شده را از وعده نتیجه جدا می‌کند.'),('ready-made-software-source-codes-benefits','محصول آماده یا توسعه اختصاصی؟ چطور انتخاب کنیم','تناسب با نیاز مهم‌تر از فهرست امکانات','هزینه مالکیت را حساب کنید','ابتدا نیاز ضروری، نیاز قابل تعویق و محدودیت تغییر را فهرست کنید. محصول آماده زمانی مفید است که فرایند اصلی شما را پوشش دهد، نه اینکه تیم مجبور شود همه کارها را با محدودیت ابزار تطبیق دهد.','قیمت خرید تنها بخشی از هزینه است. سازگاری، تمدید مجوز، پشتیبانی، آموزش و مهاجرت داده نیز باید سنجیده شود. برای توسعه اختصاصی هم دامنه نسخه اولیه و مسئول نگهداری را روشن کنید.'),('project-brief-checklist','بریف پروژه‌ای بنویسیم که قابل اجرا باشد','مسئله را به جای راه‌حل از پیش تعیین‌شده بنویسید','معیار پذیرش را مشترک تعریف کنید','به جای «یک پنل پیشرفته می‌خواهیم» توضیح دهید کدام فرایند زمان می‌برد، کاربران چه نقش‌هایی دارند و چه خطایی تکرار می‌شود. نمونه داده غیرحساس و جریان واقعی کار، ابهام را کمتر می‌کند.','برای هر خروجی توضیح دهید چه زمانی آن را کامل می‌دانید. مرور یک سناریوی واقعی بهتر از عبارتی مانند «همه چیز حرفه‌ای باشد» است. تغییر دامنه نیز باید مسیر توافق مشخص داشته باشد.'),('wordpress-maintenance-plan','پس از تحویل سایت، چه برنامه نگهداری لازم است؟','پشتیبان‌گیری با قابلیت بازیابی','به‌روزرسانی با مسیر بازگشت','وجود فایل پشتیبان کافی نیست؛ باید بدانید چه داده‌ای ذخیره می‌شود، کجا نگهداری می‌شود و چطور بازگردانی آن بررسی می‌شود. دسترسی و مدت نگهداری متناسب با ریسک کسب‌وکار تعیین می‌شود.','نسخه‌ها و وابستگی‌ها را ثبت کنید و تغییرهای حساس را ابتدا در محیط آزمایشی بررسی کنید. ثبت رخداد، مالک دسترسی و سناریوی بازگشت بخشی از برنامه نگهداری است.'),('landing-page-content-guide','صفحه فرود خوب چه پرسش‌هایی را پاسخ می‌دهد؟','ارزش را روشن و قابل فهم بیان کنید','شواهد و مسیر اقدام را متناسب انتخاب کنید','کاربر باید بفهمد خدمت برای چه کسی است، چه مسئله‌ای را حل می‌کند و گام بعدی چیست. عنوان روشن و توضیح محدودیت‌ها اغلب از انبوه صفت‌های تبلیغاتی کاربردی‌تر است.','بازخورد واقعی، نمونه‌کار مستند و توضیح فرایند می‌توانند به تصمیم کمک کنند. آمار، نشان و نقل‌قول ساختگی اعتماد نمی‌سازند. فرم را کوتاه نگه دارید و درباره استفاده از داده توضیح دهید.')]
for slug,title,h1,h2,p1,p2 in articles:
 content=f'<p>{title}؛ این راهنما بر تصمیم‌های عملی پیش از اجرا تمرکز دارد، نه وعده نتیجه قطعی.</p><h2>{h1}</h2><p>{p1}</p><h2>{h2}</h2><p>{p2}</p><h2>یک چک‌لیست کوتاه برای اقدام</h2><ul><li>وضعیت فعلی و محدودیت‌ها را ثبت کنید.</li><li>خروجی مورد انتظار و مسئول هر بخش را مشخص کنید.</li><li>اولویت‌ها و وابستگی‌ها را با تیم اجرا مرور کنید.</li><li>برای بازبینی و پذیرش خروجی زمان در نظر بگیرید.</li></ul><h2>چه چیزی را با تیم فنی در میان بگذاریم؟</h2><p>هدف کسب‌وکار، مخاطب، فرایند فعلی و محدودیت منابع را توضیح دهید. اگر پاسخ برخی پرسش‌ها هنوز مشخص نیست، آن‌ها را به‌عنوان موضوع نیازسنجی ثبت کنید، نه فرض پنهان در قرارداد.</p><h2>جمع‌بندی و قدم بعدی</h2><p>تصمیم خوب از صورت مسئله روشن و گفت‌وگوی مستند شروع می‌شود. این راهنما جایگزین بررسی اختصاصی پروژه نیست. برای انتخاب مسیر مناسب، وضعیت خود را با متخصص مرتبط مرور کنید.</p>'
 data['blog'].append({'slug':slug,'title':title,'content':content})
